  "keyRelationCoverage": [
    {
      "element": "주식회사의 법인격은 주주 개인이 아니라 구성원 단체에 부여된다.",
      "covered": false,
      "observationId": "",
      "quote": ""
    },
    {
      "element": "갑에게 자산 운용 권한이 주어지는 근거는 개인 재산 출연이 아니라 정관이나 법령에 따른 권한 부여이다.",
      "covered": false,
      "observationId": "",
      "quote": ""
    }
  ],
  "mode": "SELECTION",
  "boundary": "NONE",
  "reason": "학생은 “법인은 자기 이름으로 자산을 운용할 수 있다고 했어요.”라고 했고, 이는 지문의 법인 일반에 관한 설명과 일치한다. ②를 고른 점과 이 사실을 근거로 제시한 점에서 학생 판단은 ②가 적절하지 않다는 쪽으로 재구성된다. 다만 이 사실만으로는 법인격이 누구에게 부여되는지, 갑의 권한이 어떤 근거에서 생기는지 판단하는 연결이 확인되지 않아 근거는 충분하지 않다.",
  "reconstructability": "RECONSTRUCTABLE",
  "reconstructedPath": [
    "“법인은 자기 이름으로 자산을 운용할 수 있다고 했어요.”",
    "이 사실을 근거로 ②를 골랐으므로, 학생의 판단은 ②가 적절하지 않다는 것이다."
  ],
  "rationaleImpliedVerdict": "INVALID",
  "contentAssessment": "INSUFFICIENT",
  "insufficiencyKind": "MISSING_LINK",
  "studentEvidence": [
    {
      "observationId": "C-CP-s1",
      "quote": "법인은 자기 이름으로 자산을 운용할 수 있다고 했어요."
    }
  ],
  "sourceEvidence": [
    {
      "location": "PASSAGE",
      "quote": "주식회사는 사단 법인이면서 영리 법인으로, 법인격은 주식회사의 구성원 단체에 부여된다.",
      "mediaId": null,
      "visualObservation": null
    },
    {
      "location": "PASSAGE",
      "quote": "다만 법인은 행위 능력이 없으므로 실제 자산의 운용은 법인의 정관*이나 법령에서 권한을 부여한 사람에 의해 이루어진다.",
      "mediaId": null,
      "visualObservation": null
    },
    {
      "location": "PASSAGE",
      "quote": "법인은 자신의 이름으로 권리와 의무의 주체가 되어 자산을 운용할 수 있다.",
      "mediaId": null,
      "visualObservation": null
    }
  ],
  "errors": [],
  "errorHypothesis": null,
  "selectionMismatchQuestion": null,
  "coaching": "학생은 “법인은 자기 이름으로 자산을 운용할 수 있다고 했어요.”라고 했고, 이 내용은 지문과 일치해. 다만 ②의 적절성을 판단하려면 주식회사의 법인격이 구성원 단체에 부여된다는 점과, 실제 자산 운용 권한은 정관이나 법령으로 권한을 받은 사람에게 주어진다는 점을 ②의 설명과 연결해야 해. 제시된 근거에는 그 연결이 드러나지 않아 판단 근거가 충분한지는 확인되지 않아. 정답은 ②이고, 갑의 개인 재산 출연 때문에 주식회사의 법인격이나 갑의 자산 운용 권한이 생기는 것은 아니야."
  ,
  "studentClaims": [
    {
      "observationId": "C-CP-s1",
      "quote": "법인은 자기 이름으로 자산을 운용할 수 있다고 했어요.",
      "claimAsStated": "법인은 자기 이름으로 자산을 운용할 수 있다.",
      "sourceCheck": "CONSISTENT",
      "sourceBasis": "지문은 법인이 자신의 이름으로 권리와 의무의 주체가 되어 자산을 운용할 수 있다고 설명한다."
    }
  ]
}

